<script>
import Player from './Player.svelte';import Intro from './Intro.svelte';import Catalog from './Catalog.svelte';import {separator,kind,catalogue} from './catalog.js';import Hls from 'hls.js';import {isAndroid,NativePlayer,nativeText} from './native.js';import {get,set} from 'idb-keyval';import {tick,onDestroy} from 'svelte';
let lists=$state([]),active=$state(''),page=$state('playlists'),query=$state(''),group=$state('Tutti'),favorites=$state([]),name=$state(''),url=$state(''),epgUrl=$state(''),message=$state(''),epgMessage=$state(''),playbackMode=$state('auto'),busy=$state(false),selected=$state(null),video=$state(),hls,programs=$state([]),clock=$state(Date.now());
let visibleCount=$state(100),intro=$state(true),catalogMode=$state('live'),view=$state('catalog'),playbackError=$state('');let playbackTimer;
$effect(()=>{catalogMode;visibleCount=100;});
$effect(()=>{query;group;active;visibleCount=100;});
let storageReady=$state(false);
(async()=>{try{let saved=await get('onda');if(!saved){saved=JSON.parse(localStorage.getItem('onda')||'{}');await set('onda',saved);localStorage.removeItem('onda');}lists=(saved.lists||[]).map(p=>({...p,epg:p.epg===p.source?'':p.epg}));favorites=saved.favorites||[];active=lists[0]?.id||'';if(lists.length)page='channels';}catch{message='Impossibile leggere i dati locali.';}finally{storageReady=true;}})();
const timer=setInterval(()=>clock=Date.now(),30000);onDestroy(()=>{clearInterval(timer);stop();});
let playlist=$derived(lists.find(p=>p.id===active)),channels=$derived(playlist?.channels||[]),groups=$derived(['Tutti','Preferiti',...new Set(channels.filter(c=>!separator(c)&&kind(c)===catalogMode).map(c=>c.group))]),filtered=$derived(catalogue(channels,catalogMode,query,group,favorites));
async function save(){try{await set('onda',JSON.parse(JSON.stringify({lists,favorites})));}catch{message='Impossibile salvare: controlla lo spazio disponibile sul dispositivo.';}}
function safe(s,base){if(typeof s!=='string'||!s.trim())return '';try{let u=new URL(s,base);return ['https:','http:'].includes(u.protocol)?u.href:''}catch{return ''}}
function parse(text,base){if(!text.trimStart().startsWith('#EXTM3U'))throw Error('Il file non è una playlist M3U valida.');let out=[],meta={},epg='';for(let line of text.split(/\r?\n/)){line=line.trim();if(line.startsWith('#EXTM3U'))epg=safe(line.match(/(?:x-tvg-url|url-tvg)="([^"]+)"/i)?.[1]||'',base);else if(line.startsWith('#EXTINF:')){let attrs={};for(let m of line.matchAll(/([\w-]+)="([^"]*)"/g))attrs[m[1]]=m[2];meta={name:line.slice(line.indexOf(',')+1)||'Canale',group:attrs['group-title']||'Altri',tvg:attrs['tvg-id']||'',logo:safe(attrs['tvg-logo'],base)};}else if(line&&!line.startsWith('#')){let u=safe(line,base);if(u)out.push({...meta,name:meta.name||'Canale',group:meta.group||'Altri',url:u});meta={};}}if(!out.length)throw Error('Nessun canale HTTP/HTTPS trovato.');return {channels:out,epg};}
async function fetchText(u){if(isAndroid)return nativeText(u);if(!safe(u))throw Error('Inserisci un URL HTTP o HTTPS valido.');let r=await fetch(u,{signal:AbortSignal.timeout(20000)});if(!r.ok)throw Error('La sorgente ha risposto con errore '+r.status);return r.text();}
async function add(file){busy=true;message='';try{let text=file?await file.text():await fetchText(url);let parsed=parse(text,file?undefined:url);let p={id:Array.from(crypto.getRandomValues(new Uint8Array(16)),b=>b.toString(16).padStart(2,'0')).join(''),name:name.trim()||file?.name||'La mia playlist',source:file?'':url,...parsed,epg:safe(epgUrl)||parsed.epg,updated:Date.now()};lists=[...lists,p];active=p.id;save();name='';url='';epgUrl='';page='channels';loadEpg();}catch(e){message=e.message+' Se la sorgente è remota, verifica che consenta CORS.';}finally{busy=false;}}
async function refresh(p){busy=true;try{let parsed=parse(await fetchText(p.source),p.source);lists=lists.map(x=>x.id===p.id?{...x,...parsed,epg:x.epg||parsed.epg,updated:Date.now()}:x);save();message='Playlist aggiornata.';}catch(e){message='Aggiornamento fallito: '+e.message;}finally{busy=false;}}
function remove(id){lists=lists.filter(p=>p.id!==id);if(active===id)active=lists[0]?.id||'';save();}
function favorite(c){favorites=favorites.includes(c.url)?favorites.filter(u=>u!==c.url):[...favorites,c.url];save();}
function date(s){let m=s?.match(/^(\d{4})(\d{2})(\d{2})(\d{2})(\d{2})(\d{2})?\s*([+-]\d{4})?/);return m?Date.parse(m[1]+'-'+m[2]+'-'+m[3]+'T'+m[4]+':'+m[5]+':'+(m[6]||'00')+(m[7]?m[7].slice(0,3)+':'+m[7].slice(3):'Z')):NaN;}
let epgRequest=0;
async function loadEpg(file){const request=++epgRequest;const owner=active;epgMessage='';programs=[];if(!file&&!playlist?.epg)return;try{let doc=new DOMParser().parseFromString(file?await file.text():await fetchText(playlist.epg),'text/xml');if(request!==epgRequest||owner!==active)return;if(doc.querySelector('parsererror')||!doc.querySelector('tv'))throw Error('XML non valido');programs=[...doc.querySelectorAll('programme')].map(p=>({channel:p.getAttribute('channel'),start:date(p.getAttribute('start')),end:date(p.getAttribute('stop')),title:p.querySelector('title')?.textContent||'',description:p.querySelector('desc')?.textContent||''}));epgMessage='Guida TV caricata.';}catch{if(request===epgRequest&&owner===active)epgMessage='Guida TV non disponibile: verifica la sorgente XMLTV. Questo non impedisce la riproduzione dei canali.';}}
function now(c){return programs.find(p=>p.channel===c.tvg&&p.start<=clock&&p.end>clock)}
function next(c){return programs.filter(p=>p.channel===c.tvg&&p.start>clock).sort((a,b)=>a.start-b.start)[0]}
function time(t){return new Date(t).toLocaleTimeString('it',{hour:'2-digit',minute:'2-digit'})}
function stop(){clearTimeout(playbackTimer);hls?.destroy();hls=null;if(video){video.pause();video.removeAttribute('src');video.load();}}
let playRequest=0, fallbackUsed=false;
function fail(text){clearTimeout(playbackTimer);playbackError=text;hls?.destroy();hls=null;if(video){video.pause();video.removeAttribute('src');video.load();}}
function startHls(c,request){
 fallbackUsed=true;
 if(video.canPlayType('application/vnd.apple.mpegurl')){video.src=c.url;video.play().catch(()=>{});return;}
 if(!Hls.isSupported()){fail('Questo browser non supporta HLS. Apri la sorgente con un player esterno.');return;}
 hls=new Hls();hls.on(Hls.Events.ERROR,(_,d)=>{if(request!==playRequest||!d.fatal)return;const status=d.response?.code;fail(status?'La sorgente ha risposto con HTTP '+status+'. Verifica accesso e validità del link.':d.type===Hls.ErrorTypes.NETWORK_ERROR?'Il browser non riesce a leggere lo stream: possibili permessi CORS, errore di rete o accesso negato. Il browser non permette di distinguere sempre queste cause.':'Il contenuto non è HLS valido oppure usa codec non supportati dal browser.');});
 hls.on(Hls.Events.MANIFEST_PARSED,()=>{if(request===playRequest)video?.play().catch(()=>{});});hls.loadSource(c.url);hls.attachMedia(video);
}
function mediaError(){if(!video?.getAttribute('src')||page!=='player'||playbackError)return;
 if(playbackMode==='auto'&&!fallbackUsed&&!/\.(mp4|mkv|avi|mov|webm|m4v)(?:[?#]|$)/i.test(selected.url)&&Hls.isSupported()){video.removeAttribute('src');video.load();startHls(selected,playRequest);return;}
 fail(video.error?.code===2?'Download dello stream fallito. Verifica la connessione e i permessi della sorgente.':'Formato o codec non riproducibile in questo browser, oppure accesso alla sorgente negato. Il supporto di VLC è diverso da quello del browser.');
}
function exportSelected(){const blob=new Blob(['#EXTM3U\n#EXTINF:-1,'+selected.name.replace(/[\r\n]/g,' ')+'\n'+selected.url+'\n'],{type:'audio/x-mpegurl'});const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='TucaTV-stream.m3u';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
async function play(c){
 if(separator(c)){message='Questa voce è un separatore: seleziona un canale reale.';return;}
 if(isAndroid){message='';try{const pool=filtered;const index=pool.findIndex(x=>x.url===c.url);const start=Math.max(0,index-50);await NativePlayer.play({url:c.url,title:c.name,queue:pool.slice(start,index+51).map(x=>({url:x.url,title:x.name})),index:index-start});}catch{message='Impossibile aprire il player Android.';}return;}
 const request=++playRequest;stop();selected=c;page='player';message='';playbackError='';fallbackUsed=false;await tick();if(request!==playRequest||page!=='player')return;
 if(location.protocol==='https:'&&new URL(c.url).protocol==='http:'){fail('TucaTV non ha avviato questa sorgente HTTP dalla pagina HTTPS, per evitare blocchi o aggiornamenti automatici del link da parte del browser. Usa l’app Android o VLC; per il player web richiedi al gestore una sorgente HTTPS compatibile.');return;}
 playbackTimer=setTimeout(()=>{if(request===playRequest&&video.readyState<2)fail('La sorgente non ha fornito video entro 20 secondi. Verifica il link e i permessi CORS oppure aprila in VLC.');},20000);
 const isHls=/\.m3u8(?:[?#]|$)|[?&]output=m3u8(?:&|$)/i.test(c.url);
 if(playbackMode==='hls'||(playbackMode==='auto'&&isHls))startHls(c,request);else{video.src=c.url;video.play().catch(()=>{});}
}
function nav(p){++playRequest;stop();page=p;message='';}
function demo(){let p={id:Array.from(crypto.getRandomValues(new Uint8Array(16)),b=>b.toString(16).padStart(2,'0')).join(''),name:'Playlist di esempio',channels:[{name:'Big Buck Bunny',kind:'vod',group:'Demo',tvg:'',url:'https://test-streams.mux.dev/x36xhzz/x36xhzz.m3u8'},{name:'Sintel',group:'Demo',tvg:'',url:'https://storage.googleapis.com/gtv-videos-bucket/sample/Sintel.mp4'}],updated:Date.now(),source:'',epg:''};lists=[...lists,p];active=p.id;save();page='channels';catalogMode='vod';programs=[];}
function changeChannel(step){const pool=filtered;const i=pool.findIndex(c=>c.url===selected?.url);if(pool.length)play(pool[(i+step+pool.length)%pool.length]);}
function keys(e){if(e.defaultPrevented)return;if(e.key==='Escape'&&page==='player'){nav('channels');return;}if(!['ArrowDown','ArrowUp','ArrowLeft','ArrowRight'].includes(e.key)||['INPUT','SELECT','VIDEO'].includes(document.activeElement.tagName))return;const current=document.activeElement.getBoundingClientRect();let candidates=[...document.querySelectorAll('button,input,select,a')].filter(x=>x.offsetParent!==null&&!x.disabled&&x!==document.activeElement&&!x.closest('.concealed'));let vertical=['ArrowDown','ArrowUp'].includes(e.key),sign=['ArrowDown','ArrowRight'].includes(e.key)?1:-1;let ranked=candidates.map(el=>{let r=el.getBoundingClientRect(),dx=r.x+r.width/2-current.x-current.width/2,dy=r.y+r.height/2-current.y-current.height/2;return {el,primary:(vertical?dy:dx)*sign,secondary:Math.abs(vertical?dx:dy)};}).filter(x=>x.primary>1).sort((a,b)=>(a.primary+a.secondary*3)-(b.primary+b.secondary*3));(ranked[0]?.el||candidates[0])?.focus();e.preventDefault();}

</script>
<svelte:window onkeydown={keys}/>
{#if intro}<Intro ondone={()=>intro=false}/>{/if}
<div class="shell" inert={intro}>
<aside><a class="brand" href="#home" onclick={()=>nav('playlists')}><img class="brand-mark" src="/tucatv-mark.svg" alt="Becco di tucano"/> TucaTV<span class="beta">BETA</span></a><div class="navlabel">IL TUO SPAZIO TV</div><button class:chosen={page==='channels'} onclick={()=>nav('channels')}>▦ <span>Catalogo</span></button><button class:chosen={page==='playlists'} onclick={()=>nav('playlists')}>▤ <span>Le mie playlist</span></button><button onclick={()=>{nav('channels');group='Preferiti'}}>♡ <span>Preferiti</span><small>{favorites.length}</small></button><div class="asidebottom"><span class="dot"></span> Tutto sul tuo dispositivo<p>Nessun account. Solo la tua TV.</p><small>TucaTV / VERSIONE 0.4</small></div></aside>
<main><header><span>{page==='playlists'?'LIBRERIA':page==='player'?'IN RIPRODUZIONE':'IL TUO CATALOGO'}</span><div><span class="dot"></span> {isAndroid?'Android · VLC':'Browser'} <span class="clock">{time(clock)}</span></div></header>
{#if message}<div class="notice" role="status">{message}<button onclick={()=>message=''} aria-label="Chiudi messaggio">×</button></div>{/if}
{#if !storageReady}<div class="empty">Caricamento della raccolta…</div>{:else if page==='playlists'}
<div class="heading"><div><p class="eyebrow">LA TV, A MODO TUO</p><h1>Le mie playlist<span>.</span></h1><p>Un posto per tutti i tuoi canali. Il resto rimane fuori.</p></div><span class="counter">{lists.length} playlist</span></div>
<div class="importgrid"><section class="panel"><div class="sectiontitle"><span class="iconbox">＋</span><div><h2>Aggiungi una playlist</h2><p>Collega una sorgente e inizia a guardare.</p></div></div><label>Nome della playlist<input bind:value={name} placeholder="Es. TV di casa"/></label><label>Link M3U<input bind:value={url} type="url" placeholder="https://esempio.it/playlist.m3u"/></label><label>Guida TV · opzionale<input bind:value={epgUrl} type="url" placeholder="URL della guida XMLTV"/></label><button class="primary full" disabled={busy||!url} onclick={()=>add() }>{busy?'Caricamento…':'Aggiungi playlist'} <span>↗</span></button><div class="divider">oppure</div><label class="upload">↥ <b>Carica un file M3U</b><span>Scegli un file dal dispositivo</span><input type="file" accept=".m3u,.m3u8" disabled={busy} onchange={e=>{if(e.target.files[0])add(e.target.files[0]);e.target.value=''}}/></label></section><section class="intro"><div class="orbit"><img src="/tucatv-mark.svg" alt=""/></div><p class="eyebrow">MENO DISTRAZIONI. PIÙ TV.</p><h2>Premi play.<br/>Sentiti a casa.</h2><p>Le tue playlist, i tuoi preferiti e una guida essenziale. Tutto in un’interfaccia che lascia spazio a ciò che guardi.</p><button class="textbutton" onclick={demo}>Esplora con una playlist demo ↗</button><small>Due video di esempio · nessun canale incluso</small></section></div>
<div class="sectionrow"><h2>La tua raccolta</h2><span>Salvata sul dispositivo</span></div>{#if !lists.length}<div class="empty compact">La tua prossima visione comincia qui.<p>Aggiungi la prima playlist o esplora la demo.</p></div>{/if}<div class="collection">{#each lists as p}<article class="playlistcard"><span class="iconbox">▤</span><h3>{p.name}</h3><p>{p.channels.length} canali · {p.source?'Sorgente online':'File locale'}</p><small>Aggiornata {new Date(p.updated).toLocaleDateString('it')}</small><div class="actions"><button class="primary" onclick={()=>{active=p.id;group='Tutti';page='channels';loadEpg()}}>Apri →</button>{#if p.source}<button disabled={busy} onclick={()=>refresh(p)}>Aggiorna</button>{/if}<button onclick={()=>remove(p.id)} aria-label={'Elimina '+p.name}>Elimina</button></div></article>{/each}</div>
{:else if page==='channels'}
<div class="heading"><div><p class="eyebrow">SCEGLI COSA GUARDARE</p><h1>{catalogMode==='live'?'Live TV':'On demand'}<span>.</span></h1><p>{catalogMode==='live'?'Il mondo, in diretta.':'Scegli una storia. Premi play.'}</p></div><select bind:value={active} onchange={()=>{group='Tutti';loadEpg()}} aria-label="Playlist">{#each lists as p}<option value={p.id}>{p.name}</option>{/each}</select></div>
{#if channels.length}<div class="catalog-tabs"><button class:active={catalogMode==='live'} aria-pressed={catalogMode==='live'} onclick={()=>{catalogMode='live';group='Tutti'}}>● Live TV</button><button class:active={catalogMode==='vod'} aria-pressed={catalogMode==='vod'} onclick={()=>{catalogMode='vod';group='Tutti'}}>▶ Film e serie</button><div class="top-spacer"></div><button class:active={view==='catalog'} onclick={()=>view='catalog'} aria-label="Vista catalogo">▦</button><button class:active={view==='list'} onclick={()=>view='list'} aria-label="Vista elenco">☷</button></div>{#if epgMessage}<div class="notice" role="status">{epgMessage}</div>{/if}<div class="toolbar"><input class="search" bind:value={query} placeholder="Cerca nel catalogo…" aria-label="Cerca nel catalogo"/><label class="epgbutton">↥ Importa EPG<input type="file" accept=".xml" onchange={e=>{if(e.target.files[0])loadEpg(e.target.files[0]);e.target.value=''}}/></label></div><div class="catalog-filters"><label>Categoria<select bind:value={group}>{#each groups as g}<option value={g}>{g}</option>{/each}</select></label><span>{filtered.length.toLocaleString('it')} titoli</span></div>{#if view==='catalog'&&group==='Tutti'&&!query}<Catalog items={filtered} mode={catalogMode} {play} {favorite} {favorites} {now} oncategory={g=>{group=g;view='list'}}/>{:else}<div class="sectionrow"><span>{filtered.length} TITOLI</span><span>IN ONDA / A SEGUIRE</span></div><div class="channels">{#each filtered.slice(0,visibleCount) as c,i}<article class="channel"><button class="channelmain" onclick={()=>play(c)}><span class="num">{String(i+1).padStart(2,'0')}</span><span class="channelicon">{#if c.logo}<img src={c.logo} alt="" loading="lazy" onerror={e=>e.target.style.display='none'}/>{:else}{c.name.slice(0,2).toUpperCase()}{/if}</span><div><h3>{c.name}</h3><p>{c.group}</p></div><div class="program"><b>{now(c)?.title||'Programmazione non disponibile'}</b><p>{next(c)?time(next(c).start)+' · '+next(c).title:'Importa una guida XMLTV per vedere i programmi'}</p></div><span class="playicon">▶</span></button><button class="fav" aria-label="Preferito" aria-pressed={favorites.includes(c.url)} onclick={()=>favorite(c)}>{favorites.includes(c.url)?'♥':'♡'}</button></article>{/each}</div>{#if filtered.length>visibleCount}<button onclick={()=>visibleCount+=100}>Mostra altri 100 canali ({visibleCount} di {filtered.length})</button>{/if}{#if !filtered.length}<div class="empty">Nessun titolo trovato.</div>{/if}{/if}{:else}<div class="empty"><h2>Il tuo schermo ti aspetta.</h2><p>Aggiungi una playlist per trovare qui tutti i tuoi canali.</p><button class="primary" onclick={()=>nav('playlists')}>Aggiungi playlist ↗</button></div>{/if}
{:else}
<div class="watch-heading"><button class="textbutton" onclick={()=>nav('channels')}>← La tua TV</button><span>TUCA PLAYER</span></div>
<Player error={playbackError} onexternal={exportSelected} {video} channel={selected} programme={now(selected)} favorite={favorites.includes(selected.url)} mode={playbackMode} onback={()=>nav('channels')} onprevious={()=>changeChannel(-1)} onnext={()=>changeChannel(1)} onretry={()=>play(selected)} onfavorite={()=>favorite(selected)} onmode={m=>{playbackMode=m;play(selected)}}>
<video bind:this={video} autoplay playsinline onloadeddata={()=>clearTimeout(playbackTimer)} onerror={mediaError}><track kind="captions"/></video>
</Player><div class="watch-info"><div><p class="eyebrow">{kind(selected)==='vod'?'ON DEMAND':'A SEGUIRE'}</p><h2>{kind(selected)==='vod'?selected.name:next(selected)?.title||'Il prossimo programma, quando disponibile.'}</h2><p>{kind(selected)==='vod'?'On demand · '+selected.group:next(selected)?time(next(selected).start):'Collega una guida XMLTV alla tua playlist.'}</p></div><div class="keyboard-hint">Spazio · Play / pausa<br/>F · Schermo intero</div></div>

{/if}<footer>TucaTV <span>La tua TV. Il tuo ritmo.</span><span>Playlist e preferiti restano su questo dispositivo.</span></footer></main></div>
